// Signed callback JSON, posted as the exact canonical bytes in callback_body:
// candidate_id, playbook_id, case_id, t_approval_queued, t_callback_verified
const body = ($json && $json.body) ? $json.body : ($json || {});
const base = String(body.contract_base_url || 'http://host.docker.internal:8766').replace(/\/$/, '');
const helpers = this.helpers;

async function postExact(path, canonical, signature, idemKey) {
  try {
    const response = await helpers.httpRequest({
      method: 'POST',
      url: base + path,
      body: String(canonical || ''),
      headers: {
        'Content-Type': 'application/json',
        'X-ThreatFusion-Signature-256': String(signature || ''),
        'X-Idempotency-Key': String(idemKey || ''),
      },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: false,
    });
    const status = Number(response.statusCode || 0);
    let data = response.body;
    if (typeof data === 'string') {
      try { data = JSON.parse(data || '{}'); } catch (err) { data = {}; }
    }
    if (!data || typeof data !== 'object') data = {};
    return { status, data, error: '' };
  } catch (err) {
    return { status: Number(err.statusCode || 0), data: {}, error: String(err.message || err) };
  }
}

let verifyStatus = 0;
let stateVerified = false;
let transportError = '';
const verified = await postExact(
  '/api/v1/soar/verify-state',
  body.verify_body,
  body.verify_signature,
  body.verify_idempotency_key
);
verifyStatus = verified.status;
transportError = verified.error || '';
stateVerified = verified.status === 200 && verified.data && verified.data.state_verified === true;

let mispStatus = null;
let privateIpGuard = false;
if (stateVerified && body.target_value) {
  try {
    const response = await helpers.httpRequest({
      method: 'POST',
      url: base + '/attributes/restSearch',
      body: {
        returnFormat: 'json',
        value: String(body.target_value),
        type: 'ip-dst',
      },
      headers: {
        'Content-Type': 'application/json',
        'Authorization': String($env.THREATFUSION_MISP_API_KEY || ''),
      },
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      json: true,
    });
    mispStatus = Number(response.statusCode || 0);
    privateIpGuard = mispStatus === 422;
  } catch (err) {
    mispStatus = Number(err.statusCode || 0);
    privateIpGuard = mispStatus === 422;
    transportError = transportError || String(err.message || err);
  }
}

let callbackStatus = 0;
let callbackRecorded = false;
let tResponse = null;
if (stateVerified && body.callback_body) {
  const callback = await postExact(
    '/api/v1/soar/callback',
    body.callback_body,
    body.callback_signature,
    body.callback_idempotency_key
  );
  callbackStatus = callback.status;
  callbackRecorded = callback.status === 200 && callback.data && callback.data.callback_recorded === true;
  if (callback.data && typeof callback.data.t_response === 'number') {
    tResponse = callback.data.t_response;
  }
  transportError = transportError || callback.error || '';
}

return {
  execution_path: 'n8n_live_container',
  state_verified: stateVerified,
  verify_status: verifyStatus,
  misp_status: mispStatus,
  private_ip_guard_triggered: privateIpGuard,
  external_lookup_performed: false,
  callback_recorded: callbackRecorded,
  callback_status: callbackStatus,
  t_response: tResponse,
  transport_error: transportError,
};
